exact_statement:
\<lbrakk>no_fail ?P (do v <- ?g;
                        _ <- stateAssert ?X [];
                        ?h v
                     od);
 corres_underlying ?S False ?nf' ?r ?P ?Q (?g >>= ?h) ?f\<rbrakk>
\<Longrightarrow> corres_underlying ?S False ?nf' ?r ?P ?Q
                   (do v <- ?g;
                       _ <- stateAssert ?X [];
                       ?h v
                    od)
                   ?f

\<lbrakk>corres_underlying ?sr ?nf ?nf' ?r ?P ?Q ?f ?g;
 \<And>s s'.
    \<lbrakk>(s, s') \<in> ?sr; ?R s; ?R' s'\<rbrakk>
    \<Longrightarrow> ?Q' s';
 \<lbrace>?P\<rbrace> ?f \<lbrace>\<lambda>_. ?R\<rbrace>;
 \<lbrace>?Q\<rbrace> ?g \<lbrace>\<lambda>_. ?R'\<rbrace>\<rbrakk>
\<Longrightarrow> corres_underlying ?sr ?nf ?nf' dc ?P ?Q ?f
                   (do _ <- ?g;
                       stateAssert ?Q' []
                    od)
